-- textfix/character_speech.lua — SINH TỰ ĐỘNG bởi tools/tao_textfix.py từ vietnamese.po.
-- ĐỪNG SỬA TAY: sửa vietnamese.po rồi chạy lại tool. Xem docstring của tool.

(function()
    textfix["\n\"Day 195 - Energy\"\n\n\"Eureka. Lunar forms radiate boundless energy. Containable. Obedient, even? Control may be possible. Endless applications... if stability holds.\"\n"] = "\n\"Ngày 195 - Năng lượng\"\n\n\"Eureka. Các dạng thể mặt trăng tỏa ra nguồn năng lượng vô biên. Có thể giam giữ. Thậm chí... biết nghe lời? Có thể kiểm soát được. Ứng dụng vô tận... nếu giữ được ổn định.\"\n"
    textfix["\n\"Day 226 - Containment Measures\"\n\n\"Area of containment necessary prior to experimentation. Consider implementing a kinetic and teleportational dampening field?\"\n"] = "\n\"Ngày 226 - Các biện pháp ngăn chặn\"\n\n\"Khu vực ngăn chặn cần thiết trước khi thử nghiệm. Hãy cân nhắc triển khai trường giảm chấn động học và dịch chuyển tức thời?\"\n"
    textfix["\n\"Day 354 - Heat Signature Detection\"\n\n\"Preliminary thermal tracking functional. However, response irregularities suggest vulnerability to rudimentary interference - false positives observed with minimal thermal masking.\"\n"] = "\n\"Ngày 354 - Phát hiện dấu hiệu nhiệt\"\n\n\"Chức năng theo dõi nhiệt sơ bộ đã hoạt động. Tuy nhiên, phản hồi bất thường cho thấy dễ bị nhiễu bởi những can thiệp thô sơ - ghi nhận kết quả dương tính giả chỉ với lớp che nhiệt tối thiểu.\"\n"
    textfix["\n\"Day 418 - Electrifying!\"\n\n\"Interesting. Can redirect controlled electric discharge for practical (and offensive) applications. Truly remarkable potential. Note to self: don appropriate insulative layers next time. That last zap was... unexpectedly exhilarating.\"\n"] = "\n\"Ngày 418 - Điện khí hóa!\"\n\n\"Thú vị. Có thể chuyển hướng dòng phóng điện có kiểm soát cho các ứng dụng thực tiễn (và tấn công). Tiềm năng thật đáng kinh ngạc. Ghi chú cho bản thân: lần sau nhớ mặc lớp cách điện thích hợp. Cú giật vừa rồi... phấn khích đến không ngờ.\"\n"
    textfix["\n\"Day 56 - Lunar Mutations Study\"\n\n\"It seems as though these strange entities that emerged from the rifts are in search of living hosts... or perhaps once living.\"\n\n\"NOTE: The following creatures warrant immediate study as I suspect they may be the most viable as hosts:\"\n\n• Frog\n• Pengull\n• Varg\n• Koalefant\n• Deerclops\n\n\"Other possible Rift entity host candidates:\"\n\n• Grass Gekko\n• Hound\n• Bearger\n• Mosling\n"] = "\n\"Ngày 56 - Nghiên cứu Đột biến Mặt Trăng\"\n\n\"Có vẻ những thực thể kỳ lạ trồi lên từ các vết nứt đang tìm kiếm vật chủ còn sống... hoặc có lẽ đã từng sống.\"\n\n\"LƯU Ý: Những sinh vật sau đây cần được nghiên cứu ngay, vì tôi ngờ rằng chúng là vật chủ khả thi nhất:\"\n\n• Ếch\n• Chim cánh cụt\n• Chó Sói\n• Voi\n• Deerclops\n\n\"Các vật chủ tiềm năng khác cho thực thể Vết Nứt:\"\n\n• Tắc Kè Cỏ\n• Chó\n• Gấu Lửng\n• Ngỗng con\n"
    textfix["\n\"Day 89 - Material Study\"\n\n\"Thulecite appears sufficient to contain lunar entities. Structural integrity holds under moderate strain. Further testing advised.\"\n"] = "\n\"Ngày 89 - Nghiên cứu Vật liệu\"\n\n\"Thulecite dường như đủ để chứa các thực thể mặt trăng. Tính toàn vẹn cấu trúc được duy trì dưới sức căng vừa phải. Nên thử nghiệm thêm.\"\n"
    textfix["\n*Grows a magnificent beard"] = "\n*Sở hữu bộ râu tuyệt đẹp"
    textfix["\nCan fix easy, florp!"] = "\nCó thể sửa chữa dễ dàng, florp!"
    textfix["\nCan fix it!"] = "\nCó thể sửa được!"
    textfix["\nDon't worry, I know how to fix it!"] = "\nĐừng lo, tôi biết cách khắc phục!"
    textfix["\nI CAN FIX THIS"] = "\nTÔI CÓ THỂ SỬA CÁI NÀY"
    textfix["\nI believe I could repair that."] = "\nTôi tin rằng tôi có thể sửa chữa được điều đó."
    textfix["\nI can repair this."] = "\nTôi có thể sửa cái này."
    textfix["\nI could restore it."] = "\nTôi có thể khôi phục nó."
    textfix["\nI do believe I can repair this."] = "\nTôi tin rằng tôi có thể sửa chữa được điều này."
    textfix["\nI think I can fix this!"] = "\nTôi nghĩ tôi có thể khắc phục được điều này!"
    textfix["\nI'd rather not eat the same old thing again."] = "\nTôi thà không ăn lại món cũ."
    textfix["\nI've repaired complicated timepieces, fixing this should be easy!"] = "\nTôi đã sửa chữa những chiếc đồng hồ phức tạp, việc sửa lỗi này thật dễ dàng!"
    textfix["\nIt'd be a pleasure to fix it."] = "\nRất vui được sửa nó."
    textfix["\nMighty brain could make this better!"] = "\nBộ não mạnh mẽ có thể làm điều này tốt hơn!"
    textfix["\nMy shadow puppets should be able to draw from its power..."] = "\nNhững con rối bóng của tôi có thể sử dụng sức mạnh của nó..."
    textfix["\nSelect a random survivor"] = "\nChọn một người sống sót ngẫu nhiên"
    textfix["\nUnlike my heart, this could be mended."] = "\nKhông giống như trái tim tôi, điều này có thể được hàn gắn."
    textfix["\nWe can repair it."] = "\nChúng ta có thể sửa nó."
    textfix[" - No Bind - "] = " - Chưa có nút - "
    textfix[" -- Select new input -- "] = " -- Chọn nút nhập đầu vào -- "
    textfix[" / MIN"] = " / Phút"
    textfix[" / SEC"] = " / Giây"
    textfix[" Are those scales wooden? Interesting."] = "Mấy cái vảy kia bằng gỗ à? Thú vị đấy."
    textfix[" Day"] = " Ngày"
    textfix[" Days"] = " Ngày"
    textfix[" HA HA"] = "HÀ HÀ"
    textfix[" Happy now? What do I get?"] = "Vừa lòng chưa? Tôi được gì nào?"
    textfix[" I'll show you my GOOD lures."] = "Tôi sẽ cho bạn xem những mồi câu XỊN của tôi."
    textfix[" INSULATION"] = "CÁCH NHIỆT"
    textfix[" ITEMS"] = "VẬT PHẨM"
    textfix[" PLANAR DAMAGE"] = "SÁT THƯƠNG VỊ DIỆN"
    textfix[" PLANAR DEFENSE"] = "PHÒNG THỦ VỊ DIỆN"
    textfix[" RANGE"] = " PHẠM VI"
    textfix[" SPLASH DAMAGE"] = "SÁT THƯƠNG LAN"
    textfix[" USES"] = "LẦN DÙNG"
    textfix[" from split screen"] = "khỏi chế độ chia màn hình"
    textfix[" in the caves"] = " trong các hang động"
    textfix[" to Disconnect"] = " để ngừng kết nối"
    textfix["\" from your ban list?\nThis will affect all servers you create."] = "\" khỏi danh sách cấm của bạn?\nĐiều này sẽ ảnh hưởng đến tất cả máy chủ bạn tạo."
    textfix["\"'Neath full moon's light, ye place the key;\nA rod whose call the stars doth heed.\nBut be ye warned, 'fore prize be claimed,\nSurvive the horde, lest ye be maimed.\""] = "\"Dưới ánh trăng rằm, hãy đặt chìa khóa vào;\nCây gậy mà tiếng gọi được sao trời nghe theo.\nNhưng hãy cảnh giác, trước khi nhận phần thưởng,\nPhải sống sót qua đám quái, kẻo mang thương tật.\""
    textfix["\"A Pinetree Pioneer is always prepared!\""] = "\"Hướng Đạo Sinh Pinetree luôn sẵn sàng!\""
    textfix["\"A Pinetree Pioneer is patient and polite.\" But uh, hurry up please?"] = "\"Hướng Đạo Sinh Cây Thông luôn kiên nhẫn và lịch sự.\" Nhưng ừm, nhanh lên giùm nhé?"
    textfix["\"A Task Complete\""] = "\"Nhiệm vụ đã hoàn thành\""
    textfix["\"A flare was sent up from the forest last night. I know I should have set out immediately to help, but... well... I suppose I hesitated too long by the comforting glow of my campfire, and before I knew it the flare had faded from view. I do hope whoever it was is alright...\" -W"] = "\"Đêm qua có ai đó bắn Pháo Sáng lên từ trong rừng. Tôi biết lẽ ra tôi nên lập tức đến giúp, nhưng... à... có lẽ tôi đã chần chừ quá lâu bên ánh lửa trại ấm áp, và khi tôi kịp nhận ra thì Pháo Sáng đã tắt mất. Mong rằng người đó vẫn ổn...\" -W"
    textfix["\"A mighty Winter's Feast makes Wolfgang even mightier!\""] = "\"Lễ Hội Mùa Đông hoành tráng làm Wolfgang càng thêm mạnh!\""
    textfix["\"A princely guise, with moonlit ties!\""] = "\"Phong thái hoàng tử, kết duyên cùng ánh trăng!\""
    textfix["\"A rose to symbolize the flames of passion.\""] = "\"Một đóa hồng tượng trưng cho ngọn lửa đam mê.\""
    textfix["\"A sickly, sweet rose, plucked in its prime. Why?\""] = "\"Một đóa hồng ngọt ngào mà ốm yếu, bị ngắt khi đang độ xuân thì. Vì sao?\""
    textfix["\"ALL FLESHLINGS WILL BE CRUSHED\""] = "\"MỌI SINH VẬT THỊT SẼ BỊ NGHIỀN NÁT\""
    textfix["\"ART\" IS JUST RECREATING STUFF YOU SEE LYING AROUND"] = "\"NGHỆ THUẬT\" CHỈ LÀ TÁI TẠO NHỮNG THỨ NẰM LĂN LÓC XUNG QUANH"
    textfix["\"Abigail and I never fight.\""] = "\"Abigail và tôi chẳng bao giờ cãi nhau.\""
    textfix["\"Abigail and I shared everything.\""] = "\"Abigail và tôi từng chia nhau mọi thứ.\""
    textfix["\"Abigail? Come back! I'm not done playing with you.\""] = "\"Abigail? Quay lại đi! Chị chưa chơi với em xong mà.\""
    textfix["\"After some experimentation, I've discovered the perfect ratio of holly and jolly.\""] = "\"Sau vài thí nghiệm, tôi đã tìm ra tỷ lệ hoàn hảo giữa nhựa ruồi và niềm vui.\""
    textfix["\"Age makes fools of us all.\""] = "\"Tuổi tác biến tất cả chúng ta thành kẻ ngốc.\""
    textfix["\"Ah, the reckless abandon of youth. To think I used to dabble in fiction...\""] = "\"À, sự phóng túng liều lĩnh của tuổi trẻ. Nghĩ lại mà xem, ta từng mày mò viết tiểu thuyết...\""
    textfix["\"Ah, to see the world through rose-colored glasses.\""] = "\"À, được nhìn thế giới qua lăng kính màu hồng.\""
    textfix["\"Ahhh. Home\""] = "\"Ahhh. Nhà\""
    textfix["\"All can be lost except my taste!\""] = "\"Mất gì cũng được, trừ vị giác của tôi!\""
    textfix["\"All fire, all the time!!\""] = "\"Lửa, lửa và lửa, lúc nào cũng lửa!!\""
    textfix["\"All it takes is a spark of genius.\""] = "\"Chỉ cần một tia sáng thiên tài.\""
    textfix["\"All the wörld's a stage. För me!\""] = "\"Cả thế giới là sân khấu. Của ta!\""
    textfix["\"All those who oppose me shall perish!\""] = "\"Kẻ nào chống lại ta sẽ phải diệt vong!\""
    textfix["\"All will bathe in the prettiest of flames.\""] = "\"Tất cả sẽ tắm trong ngọn lửa đẹp nhất.\""
    textfix["\"All... will rot...\""] = "\"Tất cả ... sẽ thối rữa ...\""
    textfix["\"Alter is good. Alter shall not forsake us. Alter shall return.\""] = "\"Alter là thiện. Alter sẽ không bỏ rơi chúng ta. Alter sẽ trở lại.\""
    textfix["\"Alter is our Champion. Alter is the Champion. The Champion is Alter.\""] = "\"Alter là Nhà Vô Địch của chúng tôi. Alter là Nhà Vô Địch. Nhà Vô Địch là Alter.\""
    textfix["\"Alter\"?"] = "\"Thay đổi\"?"
    textfix["\"Alter, Glorious Moon in the cold night sky. Cast your Life-giving Light on us forever.\""] = "\"Alter, Vầng Trăng Vinh Quang trên bầu trời đêm lạnh giá. Xin chiếu Ánh Sáng ban sự sống lên chúng tôi mãi mãi.\""
    textfix["\"Always hold the board steady. Remember, a sharp knife is safer than a dull one.\nDon't forget.\""] = "\"Luôn giữ chặt tấm thớt. Nhớ nhé, dao sắc an toàn hơn dao cùn.\nĐừng quên đấy.\""
    textfix["\"Am poison, no eat!\""] = "\"Là độc đó, không được ăn!\""
    textfix["\"Am sugarplum fairy, florp. Gimme plums!\""] = "\"Là tiên kẹo mận, florp. Đưa mận đây!\""
    textfix["\"An air of mystery is the secret ingredient for any good soiree.\""] = "\"Không khí bí ẩn là thành phần bí mật cho bất kỳ buổi dạ hội hấp dẫn nào.\""
    textfix["\"And don't come back.\""] = "\"Và đừng quay lại.\""
    textfix["\"And just a dash of sweet rosewater.\""] = "\"Và chỉ thêm một chút nước hoa hồng ngọt ngào.\""
    textfix["\"And your hair has become very white;"] = "\"Và tóc cha đã bạc trắng cả;"
    textfix["\"Anything can be fixed with hard work and elbow grease.\""] = "\"Việc gì cũng sửa được, miễn chịu khó và chịu bẩn tay.\""
    textfix["\"Applause röars as red, red röses flööd my stage!\""] = "\"Tiếng vỗ tay vang dội khi những đóa hồng đỏ thắm ngập tràn sân khấu của tôi!\""
    textfix["\"April showers bring May flowers.\""] = "\"Mưa tháng Tư gọi hoa tháng Năm về.\""
    textfix["\"As usual, the responsibility of organizing the seasonal festivities falls to me.\""] = "\"Như thường lệ, việc tổ chức lễ hội theo mùa lại đổ lên đầu ta.\""
    textfix["\"Ashes, ashes, we all fall down.\""] = "\"Tro tàn, tro tàn, chúng ta đều rơi xuống.\""
    textfix["\"At times we sacrifice, at times we're sacrificed.\""] = "\"Có lúc ta hy sinh, có lúc ta bị hiến tế.\""
    textfix["\"Authored by C.W.\""] = "\"Tác giả: C.W.\""
    textfix["\"BOW BEFORE ME, FLESHLINGS!\""] = "\"CÚI ĐẦU TRƯỚC TA, LŨ THỊT DA!\""
    textfix["\"Baaaah\" yourself!"] = "Tự đi mà kêu \"baaaah\"!"
    textfix["\"Behöld Mani's chösen warriör!\""] = "\"Hãy chiêm ngưỡng chiến binh được thần Mani chọn!\""
    textfix["\"Beware.\" Beware of what?"] = "\"Coi chừng.\" Coi chừng cái gì?"
    textfix["\"Blast this heat! Where's a nice, chilled drink when you need it?\" -M"] = "\"Cái nóng chết tiệt! Lúc cần thì chẳng thấy ly nước mát lạnh nào cả.\" -M"
    textfix["\"Blue\" is an odd adjective for a flavor, but I can't disagree."] = "\"Xanh\" là một tính từ kỳ quặc để chỉ một hương vị, nhưng tôi không thể không đồng ý."
    textfix["\"Bound together are these chambers, yet in ways unnatural, wrought to confound all who enter.\""] = "\"Những gian phòng này được liên kết với nhau, nhưng theo cách phi tự nhiên, được tạo ra để khiến mọi kẻ bước vào phải bối rối.\""
    textfix["\"Brought to you by the Heralds of Tenebrau.\""] = "\"Được mang đến bởi Sứ Giả của Tenebrau.\""
    textfix["\"Brrr... it's a good thing you already have your own winter coat, Woby!\""] = "\"Brrr... may mà cậu có sẵn áo khoác mùa đông của riêng mình, Woby!\""
    textfix["\"By Hel's fire\" is a turn of phrase, dear."] = "\"Lửa của Hel\" chỉ là một cách nói thôi, cháu à."
    textfix["\"By the pricking of my thumbs, something wicked this way comes!\""] = "\"Ngón tay cái ta ngứa ran, có kẻ gian tà đang tới gần!\""
    textfix["\"CRACKING WALNUT CODE\""] = "\"ĐANG BẺ KHÓA MÃ QUẢ ÓC CHÓ\""
    textfix["\"Call förth the höwling winds and biting cöld, the jötnar fear them nöt!\""] = "\"Cứ gọi cả gió gào lẫn giá rét cắt da tới đây, người khổng lồ jötnar cũng chẳng sợ!\""
    textfix["\"Cargo\" is sailor-lingo for \"stuff\"."] = "\"Hàng hóa\" là thuật ngữ của thủy thủ để chỉ \"đồ vật\"."
    textfix["\"Cave lonely\""] = "\"Hang cô đơn\""
    textfix["\"Ch-chilly...\""] = "\"L-lạnh...\""
    textfix["\"Charmed, I'm sure.\""] = "\"Hân hạnh, chắc chắn rồi.\""
    textfix["\"Cold does not bother Wolfgang!\""] = "\"Lạnh không làm phiền Wolfgang!\""
    textfix["\"Combat is all about technique, dear.\""] = "\"Chiến đấu cốt ở kỹ thuật, cháu yêu.\""
    textfix["\"Come closer - we are hungry!\""] = "\"Lại gần đây - chúng ta đói rồi!\""
    textfix["\"Come closer... won't bite! (Hee-hee...)\""] = "\"Lại gần đây... không cắn đâu! (Hi hi...)\""
    textfix["\"Come on Woby, that Winter's Feast tree won't decorate itself!\""] = "\"Nhanh nào Woby, Cây Lễ Hội Mùa Đông đâu có tự trang trí được!\""
    textfix["\"Come on. Give it your best shot.\""] = "\"Nào. Tung đòn mạnh nhất ra xem.\""
    textfix["\"Come onnnn, let me fire the cannon!\""] = "\"Thôi mà, cho tôi bắn đại bác điiii!\""
    textfix["\"Could've sworn I saw one of the trees movin' when I was out choppin' firewood... must've been a trick of the light.\" -W"] = "\"Có thể thề rằng tôi đã nhìn thấy một trong những cái cây chuyển động khi tôi ra ngoài chặt củi... chắc chắn là do ánh sáng đánh lừa.\" -W"
    textfix["\"Dainty rose make Wolfgang strong, cultured man.\""] = "\"Hoa hồng mảnh mai làm Wolfgang thành người đàn ông mạnh mẽ, có văn hóa.\""
    textfix["\"Death, a necessary end, will come when it will come,\" but not today, my allies!"] = "\"Cái chết, một sự kết thúc cần thiết, sẽ đến khi nó đến,\" nhưng không phải hôm nay, các đồng minh của tôi!"
    textfix["\"Do not challenge the Mighty Wolfgang!\""] = "\"Đừng thách thức Wolfgang hùng mạnh!\""
    textfix["\"Do you believe in fairies? If you believe, clap your hands.\""] = "\"Bạn có tin vào các nàng tiên không? Nếu bạn tin, hãy vỗ tay.\""
    textfix["\"Do you ever feel adrift like a vessel without mooring?\""] = "\"Bạn có bao giờ cảm thấy trôi dạt như một con tàu không neo đậu không?\""
    textfix["\"Don't be silly, it's only a bad dream...\""] = "\"Đừng ngốc thế, chỉ là ác mộng thôi mà...\""
    textfix["\"Don't even think about it.\""] = "\"Đừng có mà nghĩ tới.\""
    textfix["\"Don't get between me and my hoard of souls.\""] = "\"Đừng có chen vào giữa tôi và kho linh hồn của tôi.\""
    textfix["\"Don't mess with us.\""] = "\"Đừng có đụng vào chúng tôi.\""
    textfix["\"Don't play with matches.\""] = "\"Đừng nghịch diêm.\""
    textfix["\"Don't slip up or you might get a face full of snow, hyuyu!\""] = "\"Đừng trượt chân nếu không mặt bạn sẽ đầy tuyết đấy, hyuyu!\""
    textfix["\"Don't start a tussle you can't finish.\""] = "\"Đừng bắt đầu một cuộc tranh đấu mà bạn không thể hoàn thành.\""
    textfix["\"Don't worry Sirs and Madams, Woby and I are on the case!\""] = "\"Thưa quý ông quý bà, đừng lo, Woby và tôi đã nhận vụ này!\""
    textfix["\"Dread twisted into devotion. Trembling into gratitude.\""] = "\"Nỗi sợ hãi biến thành sự tận tâm. Run rẩy thành lòng biết ơn.\""
    textfix["\"Dressing up not so bad sometimes.\""] = "\"Thỉnh thoảng diện đồ đẹp cũng không tệ lắm.\""
    textfix["\"EMPATHY MODULE NOT RESPONDING\""] = "\"BỘ PHẬN CẢM XÚC KHÔNG CÓ PHẢN HỒI\""
    textfix["\"Eternal\"? Ha!"] = "Mãi mãi? Ha!"
    textfix["\"Even I let my hair down occasionally.\""] = "\"Ngay cả ta thỉnh thoảng cũng thả lỏng một chút.\""
    textfix["\"Even the most majestic tree's gotta start as a seed.\""] = "\"Ngay cả cái cây hùng vĩ nhất cũng phải bắt đầu từ hạt giống.\""
    textfix["\"Every meal ends in an empty plate.\""] = "\"Bữa ăn nào rồi cũng kết thúc bằng một chiếc đĩa trống.\""
    textfix["\"Every story needs a fearless adventurer and their trusty steed!\""] = "\"Câu chuyện nào cũng cần một nhà thám hiểm gan dạ và chiến mã trung thành!\""
    textfix["\"Everything I make is magnificent.\""] = "\"Mọi thứ tôi làm ra đều tuyệt hảo.\""
    textfix["\"Extra, extra! Read all about it!\""] = "\"Tin nóng đây, tin nóng đây! Đọc ngay kẻo lỡ!\""
    textfix["\"Eye\" like it!"] = "\"Mắt\" thích đấy!"
    textfix["\"Eyes on the horizon, Woby!\""] = "\"Nhìn về phía chân trời nào, Woby!\""
    textfix["\"Fancy a matchstick, sir?\""] = "\"Ngài mua một que diêm chứ?\""
    textfix["\"Feel big fancy\""] = "\"Thấy sang quá\""
    textfix["\"Feel pretty\""] = "\"Cảm thấy xinh đẹp\""
    textfix["\"Field botany isn't my specialty... but it's growing on me.\""] = "\"Thực vật học thực địa không phải chuyên môn của tôi... nhưng tôi đang dần bén rễ với nó.\""
    textfix["\"Five more minutes.\""] = "\"Năm phút nữa.\""
    textfix["\"Follow me into the forest deep, where impish sorts frolic and play!\""] = "\"Theo tôi vào sâu trong rừng thẳm, nơi lũ tinh quái vui đùa nhảy nhót!\""
    textfix["\"Follow the instructions\", mum always said."] = "\"Hãy làm theo hướng dẫn\", mẹ luôn nói."
    textfix["\"For dark is become our shield. Our sustenance. Our solace.\""] = "\"Vì bóng tối đã trở thành lá chắn của chúng ta. Nguồn sống của chúng ta. Niềm an ủi của chúng ta.\""
    textfix["\"Forests are full of shadows, eh?\""] = "\"Rừng thì đầy bóng tối mà, hả?\""
    textfix["\"Forsaken wretches of the one who turned away.\""] = "\"Những kẻ khốn cùng bị kẻ ngoảnh mặt bỏ rơi.\""
    textfix["\"Freedom suits me.\""] = "\"Tự do phù hợp với tôi.\""
    textfix["\"Freeing him might not have been my best idea.\""] = "\"Thả hắn ra có lẽ không phải ý hay nhất của tôi.\""
    textfix["\"Frilly and gilly, florp!\""] = "\"Diềm bèo xinh, mang cá xinh, florp!\""
    textfix["\"From desolation were we drawn. Into the veiled embrace of Them.\""] = "\"Chúng ta đã bị lôi kéo khỏi sự hoang tàn. Vào trong vòng tay che đậy của Họ.\""
    textfix["\"From time to time I've spotted bottles bobbing along the ocean currents, just out of reach from the shore. I have half a mind to construct a boat and retrieve one of them... I have a gut feeling that someone is trying to send out a message.\" -W"] = "\"Thỉnh thoảng tôi nhìn thấy những cái chai bồng bềnh dọc theo dòng hải lưu, ngay ngoài tầm với của bờ biển. Tôi có ý định đóng một chiếc thuyền và lấy một trong số chúng... Tôi có linh cảm rằng ai đó đang cố gắng gửi một tin nhắn.\" -W"
    textfix["\"Glurgh, no call me shrimp! Me big scary pirate!!\""] = "\"Glurgh, không được gọi tôi là tôm tép! Tôi là cướp biển to lớn đáng sợ!!\""
    textfix["\"Golden fields of hay, ripe for burning... I mean harvesting.\""] = "\"Những cánh đồng cỏ khô vàng óng, chín tới để đốt... à, ý tôi là để gặt.\""
    textfix["\"Goodness gracious, it seems you've been annihilated.\""] = "\"Ôi trời đất, có vẻ cháu đã bị tiêu diệt rồi.\""
    textfix["\"Grrrr... We're scary!\""] = "\"Grừừừ... Chúng tôi đáng sợ lắm đó!\""
    textfix["\"Gööd tidings to all!\""] = "\"Chúc mọi người tin vui!\""
    textfix["\"Ha ha! Did I scare ya?\""] = "\"Ha ha! Sợ chưa?\""
    textfix["\"Have you found your treasure yet? When you do, will you come home?\""] = "\"Anh đã tìm thấy kho báu chưa? Khi tìm được rồi, anh sẽ về nhà chứ?\""
    textfix["\"He died before getting to see these beautiful flames.\""] = "\"Anh ta chết trước khi kịp ngắm những ngọn lửa tuyệt đẹp này.\""
    textfix["\"Heh heh, this thing's itchy.\""] = "\"He he, cái này ngứa ghê.\""
    textfix["\"Hello friend?\""] = "\"Xin chào bạn?\""
    textfix["\"Herbal\" therapy."] = "Liệu pháp 'thảo dược'."
    textfix["\"Here lies some gal.\""] = "\"Nơi đây yên nghỉ một cô nàng nào đó.\""
    textfix["\"Here lies some guy.\""] = "\"Nơi đây yên nghỉ một gã nào đó.\""
    textfix["\"Here lies some person.\""] = "\"Nơi đây yên nghỉ một người nào đó.\""
    textfix["\"Here much long... much long\""] = "\"Ở đây lâu quá... lâu quá\""
    textfix["\"Hmph. It's cold out.\""] = "\"Hừm. Ngoài trời lạnh thật.\""
    textfix["\"Hmph.\""] = "\"Hừm.\""
    textfix["\"Honest work makes an honest woman.\""] = "\"Làm ăn lương thiện mới nên người phụ nữ tử tế.\""
    textfix["\"Honest work will only get ya so far.\""] = "\"Làm ăn lương thiện thì cũng chỉ tới được chừng đó thôi.\""
    textfix["\"Honestly, a working knowledge of medicinal botany is hardly witchcraft!\""] = "\"Thành thật mà nói, kiến thức thực tế về dược liệu khó có thể coi là phép thuật phù thủy!\""
    textfix["\"Hope I don't burn the trees.\""] = "\"Hy vọng tôi không đốt cây.\""
    textfix["\"Hot bath sound nice...\""] = "\"Tắm nước nóng nghe thích...\""
    textfix["\"Hrrm... mff! Mmmf!\""] = "\"Hừm... ưm! Ưmmm!\""
    textfix["\"Hug?\""] = "\"Ôm?\""
    textfix["\"I AM THE FUTURE\""] = "\"TÔI LÀ TƯƠNG LAI\""
    textfix["\"I AM THE GOLD STANDARD\""] = "\"TÔI LÀ TIÊU CHUẨN VÀNG\""
    textfix["\"I AM THE ROOT OF ALL EVIL\""] = "\"TÔI LÀ CỘI RỄ CỦA MỌI TỘI ÁC\""
    textfix["\"I POLISHED MY CHASSIS FOR THE OCCASION\""] = "\"TÔI ĐÃ ĐÁNH BÓNG KHUNG GẦM ĐỂ DỰ DỊP NÀY\""
    textfix["\"I actually just work in the galley.\""] = "\"Thật ra tôi chỉ làm việc trong bếp tàu thôi.\""
    textfix["\"I ain't one to keep up with trends, but isn't this a bit old-fashioned?\""] = "\"Tôi chẳng phải người chạy theo mốt, nhưng cái này có hơi lỗi thời không?\""
    textfix["\"I am coming for you!\""] = "\"Ta đến bắt ngươi đây!\""
    textfix["\"I am feeling the chemistry!\""] = "\"Tôi cảm nhận được \"phản ứng hóa học\" rồi đây!\""
    textfix["\"I am in deepest mourning...\""] = "\"Tôi đang chịu tang trong nỗi đau sâu sắc nhất...\""
    textfix["\"I am mighty! No one is mightier!\""] = "\"Wolfgang mạnh mẽ! Không ai mạnh hơn!\""
    textfix["\"I am the best that ever was!!\""] = "\"Tôi là người giỏi nhất từ trước đến nay!!\""
    textfix["\"I can handle myself.\""] = "\"Tôi tự lo cho mình được.\""
    textfix["\"I can tough anything out.\""] = "\"Tôi chịu đựng được hết.\""
    textfix["\"I carry on for Abigail's sake.\""] = "\"Tôi gắng sống tiếp vì Abigail.\""
    textfix["\"I clean up pretty good, eh?\""] = "\"Tôi mà chải chuốt vào thì cũng bảnh ra phết, hả?\""
    textfix["\"I could do with a haircut and a cup of tea, eh?\""] = "\"Giá mà được cắt tóc với làm tách trà thì hay biết mấy, hả?\""
    textfix["\"I couldn't have imagined it, I'm certain I just saw a piece of the moon break off and crash into the ocean! Perhaps my compatriots will join me in a search for it...\" -W"] = "\"Tôi không thể tưởng tượng nổi, tôi chắc chắn mình vừa nhìn thấy một mảnh trăng vỡ ra và rơi xuống biển! Có lẽ đồng bào của tôi sẽ cùng tôi đi tìm nó...\" -W"
    textfix["\"I cöuld take yöu curs with öne eye behind my mask!\""] = "\"Dù chỉ nhìn bằng một mắt sau mặt nạ, tôi vẫn hạ gục được lũ chó các ngươi!\""
    textfix["\"I delight in an elegant soirée, provided it concludes at a sensible hour.\""] = "\"Tôi thích thú với một buổi dạ hội sang trọng, miễn là nó kết thúc vào một giờ hợp lý.\""
    textfix["\"I didn't do it. Really.\""] = "\"Không phải tôi làm. Thật đấy.\""
    textfix["\"I didn't like it here anyway.\""] = "\"Dù sao tôi cũng chẳng thích nơi này.\""
    textfix["\"I don't break down easy.\""] = "\"Tôi đâu có dễ hỏng hóc.\""
    textfix["\"I don't need a handbook telling me what to do - I make the rules now!\""] = "\"Tôi chẳng cần sổ tay nào dạy phải làm gì - giờ tôi mới là người đặt luật!\""
    textfix["\"I experimented with making a rudimentary compass and discovered that this place does in fact seem to have a magnetic North. Curiously, it also pointed out the positions of my fellow camp mates who, as it turned out, had already crafted similar compasses of their own.\" -W"] = "\"Tôi đã thử nghiệm chế tạo một chiếc la bàn thô sơ và phát hiện ra rằng nơi này trên thực tế dường như có một cực Bắc từ tính. Thật kỳ lạ, nó cũng chỉ ra vị trí của những người bạn cùng trại của tôi, những người hóa ra đã chế tạo ra những chiếc la bàn tương tự của riêng họ.\" -W"
    textfix["\"I fear I may no longer be able to trust my own eyes. I've been catching glimpses of strange shadowy forms at the edges of my vision with increasing frequency... surely they can't really be there?\" -W"] = "\"Tôi e rằng mình không còn tin nổi vào mắt mình nữa. Tôi ngày càng hay thoáng thấy những hình bóng kỳ lạ ở rìa tầm nhìn... chắc hẳn chúng không thật sự ở đó chứ?\" -W"
    textfix["\"I fear nöt Surtr's flames!\""] = "\"Tôi chẳng sợ ngọn lửa của Surtr!\""
    textfix["\"I feared it might injure the brain;"] = "\"Ta sợ làm thế sẽ hại đến bộ não;"
    textfix["\"I finally worked up the courage to explore the underground caverns. To my surprise, I found there was ample light provided by a most curious glowing plant that seems to grow naturally throughout the cave system. I've harvested some bulbs for further study.\" -W"] = "\"Cuối cùng tôi đã lấy hết can đảm để khám phá các hang động dưới lòng đất. Thật ngạc nhiên, tôi thấy có rất nhiều ánh sáng được cung cấp bởi một loại cây phát sáng kỳ lạ nhất dường như mọc tự nhiên khắp hệ thống hang động. Tôi đã thu hoạch một số củ để nghiên cứu thêm.\" -W"
    textfix["\"I find myself returning more and more frequently to my magnificent science machine, busying myself with prototyping new tools to aid in our survival. After all, I must do something to keep myself sane in this strange place...\" -W"] = "\"Tôi thấy mình ngày càng quay trở lại với cỗ máy khoa học tuyệt vời của mình, bận rộn với việc tạo ra các công cụ mới để hỗ trợ sự sống còn của chúng ta. Sau cùng, tôi phải làm gì đó để giữ cho mình tỉnh táo ở nơi xa lạ này...\" -W"
    textfix["\"I grow, untamed and untended.\""] = "\"Tôi cứ lớn lên, hoang dại và chẳng ai chăm.\""
    textfix["\"I hate parties.\""] = "\"Tôi ghét tiệc tùng.\""
    textfix["\"I have an urge to dance around a fire in the moonlight.\""] = "\"Tôi muốn nhảy múa quanh đống lửa dưới ánh trăng.\""
    textfix["\"I hope I don't break my glasses.\""] = "\"Mong là ta không làm vỡ kính.\""
    textfix["\"I hope I don't lose any points for the state of my uniform.\""] = "\"Tôi hy vọng mình không bị mất điểm vì tình trạng đồng phục của mình.\""
    textfix["\"I just need to find my beautiful assistant.\""] = "\"Tôi chỉ cần tìm trợ lý xinh đẹp của mình.\""
    textfix["\"I know you're still out there, my dear. I won't ever give up.\""] = "\"Em biết anh vẫn còn ở ngoài kia, mình ơi. Em sẽ không bao giờ từ bỏ.\""
    textfix["\"I know you're still there, Abigail... we'll be able to play together again soon.\""] = "\"Em biết chị vẫn ở đó, Abigail... chúng ta sẽ sớm lại được chơi cùng nhau thôi.\""
    textfix["\"I let in darkness once before, what's the harm in a little more?\""] = "\"Ta đã từng để bóng tối vào rồi, thêm một chút nữa thì có hại gì?\""
    textfix["\"I must train for the races!\""] = "\"Tôi phải luyện tập cho các cuộc đua!\""
    textfix["\"I never was one to shy away from theatrics, or a good suit.\""] = "\"Tôi chưa bao giờ ngại màn kịch tính, hay một bộ vest đẹp.\""
    textfix["\"I often look from the highest hill, that I might see my boatman...\""] = "\"Tôi thường nhìn từ ngọn đồi cao nhất để có thể nhìn thấy người chèo thuyền của mình...\""
    textfix["\"I only cook with natural ingredients.\""] = "\"Tôi chỉ nấu ăn bằng nguyên liệu tự nhiên.\""
    textfix["\"I seem to have developed quite a taste for treasure.\""] = "\"Hình như tôi đã nảy ra khẩu vị với kho báu mất rồi.\""
    textfix["\"I shall fight för the förest!\""] = "\"Tôi sẽ chiến đấu vì rừng xanh!\""
    textfix["\"I shall scare öff all the black winged beasties!\""] = "\"Tôi sẽ dọa chạy hết lũ quái vật cánh đen!\""
    textfix["\"I still have the last gift you gave me. \"A pearl for Pearl\"... remember?\""] = "\"Em vẫn còn giữ món quà cuối cùng anh tặng. \"Ngọc trai cho Pearl\"... anh nhớ không?\""
    textfix["\"I stumbled upon a rather suspicious mound of dirt... perhaps it was left by a creature of some sort? This may require further investigation...\" -W"] = "\"Tôi tình cờ thấy một ụ đất khá đáng ngờ... có lẽ nó bị một loại sinh vật nào đó để lại? Điều này có thể cần phải điều tra thêm...\" -W"
    textfix["\"I suppose I should make time to stop and smell the roses every so often.\""] = "\"Tôi cho rằng thỉnh thoảng tôi nên dành thời gian để dừng lại và ngửi mùi hoa hồng.\""
    textfix["\"I take no pleasure in this.\""] = "\"Tôi chẳng thấy vui gì với chuyện này.\""
    textfix["\"I think I really rose to the occasion! Eh, Woby?\""] = "\"Tôi thấy mình nở mày nở mặt ghê! Nhỉ, Woby?\""
    textfix["\"I used my special moustache wax.\""] = "\"Tôi đã sử dụng sáp ria mép đặc biệt của mình.\""
    textfix["\"I want to go home, but we can't find the way.\""] = "\"Tôi muốn về nhà, nhưng chúng tôi không tìm được đường.\""
    textfix["\"I will deströy my enemies!\""] = "\"Tôi sẽ tiêu diệt kẻ thù của mình!\""
    textfix["\"I will try to summon up some holiday spirit... if I must.\""] = "\"Tôi sẽ cố gắng khơi dậy tinh thần ngày lễ... nếu phải.\""
    textfix["\"I wonder if Maman missed my holiday baking.\""] = "\"Không biết Maman có nhớ những mẻ bánh ngày lễ của tôi không.\""
    textfix["\"I yearn för my chance ön the pröving gröunds!\""] = "\"Tôi khao khát cơ hội được thử sức nơi đấu trường!\""
    textfix["\"I'd say this look is best served cold.\""] = "\"Phải nói rằng bộ dạng này nên được dọn ra khi còn lạnh.\""
    textfix["\"I'd wear it more often, but it's so heavy with all these badges...\""] = "\"Tôi sẽ đeo nó thường xuyên hơn, nhưng nó quá nặng với những huy hiệu này...\""
    textfix["\"I'll conquer this world with the power of my MIND!\""] = "\"Tôi sẽ chinh phục thế giới này bằng sức mạnh của LÍ TRÍ của tôi!\""
    textfix["\"I'll keep sending messages, until one reaches you...\""] = "\"Em sẽ tiếp tục gửi thư, cho đến khi có một lá đến được tay anh...\""
    textfix["\"I'll only go to the party if Abigail comes too.\""] = "\"Tôi sẽ chỉ đi dự tiệc nếu Abigail cũng đến.\""
    textfix["\"I'm absolutely adorable!\""] = "\"Tôi thực sự đáng yêu!\""
    textfix["\"I'm on a see-food diet.\""] = "\"Tôi đang ăn kiêng kiểu thấy-gì-ăn-nấy.\""
    textfix["\"I'm simply tickled pink, hyuyu!\""] = "\"Tôi vui đến hồng cả má, hyuyu!\""
    textfix["\"I'm sure I had a scientific reason for this.\""] = "\"Tôi chắc chắn mình đã có lý do khoa học cho việc này.\""
    textfix["\"I'm thinking of opening a chocolate factory.\""] = "\"Tôi đang nghĩ đến việc mở một nhà máy sô cô la.\""
    textfix["\"I'm waiting for you. At the spot where we first met. I've been waiting so long...\""] = "\"Em đang đợi anh. Ở nơi ta gặp nhau lần đầu. Em đã đợi lâu lắm rồi...\""
    textfix["\"I've been in scraps before, eh?\""] = "\"Tôi từng ẩu đả vài trận rồi đấy, hả?\""
    textfix["\"I've been told, my blood can run cold!\""] = "\"Người ta vẫn bảo, máu tôi lạnh như băng giá!\""
    textfix["\"I've better places to be.\""] = "\"Tôi còn có nơi tốt hơn để đến.\""
    textfix["\"I've cooked up something frightful, just for you!\""] = "\"Tôi đã nấu một món đáng sợ, dành riêng cho bạn!\""
    textfix["\"I've discovered a lot of things at sea... that I'm prone to seasickness, for one.\""] = "\"Tôi đã phát hiện ra rất nhiều điều trên biển... chẳng hạn như tôi dễ bị say sóng.\""
    textfix["\"I've faced worse ordeals.\""] = "\"Tôi đã phải đối mặt với những thử thách tồi tệ hơn.\""
    textfix["\"I've finally perfected my design for an ingenious (if I do say so myself) device that stores important garden-based knowledge. Certain naysayers might point out that it looks like nothing more than an overturned flowerpot worn on the head... some people simply don't have an eye for science.\" -W"] = "\"Cuối cùng tôi đã hoàn thiện thiết kế cho một thiết bị tài tình (tự tôi khen vậy) để lưu trữ những kiến thức quan trọng về làm vườn. Vài kẻ hay chê bai có thể bảo nó trông chẳng khác gì một chậu hoa úp ngược đội trên đầu... có những người đơn giản là không có con mắt khoa học.\" -W"
    textfix["\"I've harnessed the power of the earth's core!\""] = "\"Tôi đã chế ngự được sức mạnh của lõi trái đất!\""
    textfix["\"I've the brains AND the brawn.\""] = "\"Tôi có bộ não VÀ cơ bắp.\""
    textfix["\"IF I HAD A HEART IT WOULD BE MADE OF ICE\""] = "\"NẾU TÔI CÓ TRÁI TIM, NÓ SẼ ĐƯỢC LÀM BẰNG BĂNG\""
    textfix["\"If Lucy's the belle of the ball, I guess that makes me the beast.\""] = "\"Nếu Lucy là người đẹp nhất trong vũ hội, tôi đoán điều đó khiến tôi trở thành quái vật.\""
    textfix["\"If you fight us, you will lose.\""] = "\"Đánh với chúng tôi là bạn thua đó.\""
    textfix["\"In my youth,\" Father William replied to his son,"] = "\"Khi còn trẻ,\" Cha William trả lời con trai mình,"
    textfix["\"Into woods, follow!\""] = "\"Vào rừng, theo nào!\""
    textfix["\"It called bye-oh-loomy...loominess...loomin-essence... GLOWY!\""] = "\"Nó gọi là phát-quang-sinh... sinh-phát-quang... sinh-quang-học... SÁNG SÁNG!\""
    textfix["\"It seems that every time we discover a doorway out of this terrible place, it just leads to more strange worlds with new horrors to endure. Still, I can't give up hope that one day we'll find a doorway that will take us home...\" -W"] = "\"Dường như mỗi lần chúng ta khám phá ra một cánh cửa thoát khỏi nơi khủng khiếp này, nó lại dẫn đến những thế giới kỳ lạ hơn với những nỗi kinh hoàng mới phải chịu đựng. Tuy nhiên, tôi vẫn không thể từ bỏ hy vọng rằng một ngày nào đó chúng ta sẽ tìm thấy một cánh cửa đưa chúng ta về nhà...\" -W"
    textfix["\"It takes a lot of lumber to keep a boat ship-shape, eh?\""] = "\"Muốn thuyền lúc nào cũng tươm tất thì tốn gỗ lắm đấy, hả?\""
    textfix["\"It turns out that Koalefants are a bit hardier than I expected. I (quite sensibly) decided to take a... strategic retreat until I'm better prepared.\" -W"] = "\"Hóa ra lũ Voi cứng cáp hơn tôi tưởng một chút. Tôi (khá sáng suốt) đã quyết định... rút lui chiến lược cho đến khi chuẩn bị tốt hơn.\" -W"
    textfix["\"It's a fine day for some fine dining, non?\""] = "\"Hôm nay là ngày đẹp trời để thưởng thức món ngon, non?\""
    textfix["\"It's a nice view from the top.\""] = "\"Đứng trên cao nhìn xuống, cảnh đẹp thật.\""
    textfix["\"It's almost time\"? Time for what?"] = "\"Sắp đến lúc rồi\"? Lúc gì cơ?"
    textfix["\"It's dirty down here.\""] = "\"Dưới này bẩn quá.\""
    textfix["\"It's good that we know how to make silk, our claws keep catching on the sail...\""] = "\"May mà chúng mình biết nhả tơ, móng vuốt cứ mắc vào cánh buồm hoài...\""
    textfix["\"It's not as bad as it looks.\""] = "\"Không tệ như vẻ ngoài đâu.\""
    textfix["\"It's the best game you can name!\""] = "\"Môn thể thao hay nhất trần đời, khỏi bàn!\""
    textfix["\"It's the perfect time of year for sitting in front of a roaring fire.\""] = "\"Đây là thời điểm hoàn hảo trong năm để ngồi bên đống lửa rực cháy.\""
    textfix["\"It's worse than it looks.\""] = "\"Tệ hơn vẻ ngoài đấy.\""
    textfix["\"Just follow the recipe, dear.\""] = "\"Cứ làm theo công thức là được, cháu yêu.\""
    textfix["\"Just needed a rest.\""] = "\"Chỉ cần nghỉ ngơi thôi.\""
    textfix["\"Knowledge is power!\""] = "\"Tri thức là sức mạnh!\""
    textfix["\"Last time I baited my hook with berries I caught more fish than I could carry, but when I tried today? Barely a nibble! Guess the berry trick only works on some of 'em.\" -W"] = "\"Lần trước tôi mồi lưỡi câu bằng quả mọng, câu được nhiều cá đến mức mang không xuể, nhưng hôm nay thử lại thì sao? Hầu như chẳng con nào đớp! Chắc mẹo quả mọng chỉ hiệu nghiệm với vài loài thôi.\" -W"
    textfix["\"Let ol'Winnie fix ya up somethin' special.\""] = "\"Để Winnie này nấu cho cậu món gì đặc biệt nhé.\""
    textfix["\"Let the cursed Keystone never cross this threshold.\""] = "\"Đừng bao giờ để Đá Khóa bị nguyền rủa vượt qua ngưỡng cửa này.\""
    textfix["\"Let the pursuit of knowledge stretch beyond every horizon.\""] = "\"Hãy để việc theo đuổi kiến thức vượt ra ngoài mọi chân trời.\""
    textfix["\"Let this be the party tö end all parties!\""] = "\"Hãy để đây là bữa tiệc khép lại mọi bữa tiệc!\""
    textfix["\"Let us remember the days öf öld!\""] = "\"Hãy cùng tưởng nhớ những ngày xa xưa!\""
    textfix["\"Let's get cooking!\""] = "\"Cùng nấu ăn thôi nào!\""
    textfix["\"Look out evildoers, I've got the moon on my side!\""] = "\"Coi chừng đấy lũ gian ác, mặt trăng đứng về phía tôi!\""
    textfix["\"Look, we lost a tooth!\""] = "\"Nhìn này, chúng mình vừa rụng một cái răng!\""
    textfix["\"Loyalty unending. We kneel before the undying. The unaltering.\""] = "\"Lòng trung thành bất tận. Chúng tôi quỳ trước đấng bất diệt. Đấng bất biến.\""
    textfix["\"Lucy is my sous chef.\""] = "\"Lucy là phụ bếp của tôi.\""
    textfix["\"Lucy\" was it? Oh botheration, now he's got ME talking to it!"] = "\"Lucy\" phải không? Ôi phiền thật, giờ anh ấy bắt TÔI phải nói chuyện với nó!"
    textfix["\"MEAL SERVER DOWN\""] = "\"MÁY CHỦ BỮA ĂN ĐÃ SẬP\""
    textfix["\"MEEEEEAT.\""] = "\"THỊỊỊỊỊT.\""
    textfix["\"MOTIVATIONAL SPEAKING\""] = "\"DIỄN THUYẾT TRUYỀN ĐỘNG LỰC\""
    textfix["\"Magic is merely science that hasn't been categorized yet.\""] = "\"Phép thuật chỉ là khoa học chưa được phân loại.\""
    textfix["\"Manners, my dear.\""] = "\"Phép lịch sự đâu, cháu yêu.\""
    textfix["\"Maybe fluff okay for wintertime, but scales better all other times!\""] = "\"Lông xù chắc được vào mùa đông, nhưng lúc khác thì vảy vẫn hơn!\""
    textfix["\"Maybe if I dress like them, they won't sting me!\""] = "\"Biết đâu mình ăn mặc giống tụi nó thì tụi nó sẽ không đốt mình!\""
    textfix["\"Me feel fancy, florp!\""] = "\"Tôi thấy mình sang quá, florp!\""
    textfix["\"Me look radiant on moonlit swim.\""] = "\"Tôi trông rạng rỡ khi bơi dưới ánh trăng.\""
    textfix["\"Me ready fight dirty.\""] = "\"Tôi sẵn sàng chơi bẩn.\""
    textfix["\"Me scary dragon! Gonna gobble up all the princesses, hee-hee!\""] = "\"Tôi là con rồng đáng sợ! Sẽ nuốt chửng tất cả các công chúa, hee-hee!\""
    textfix["\"Mermfolk Ownlee\"... hmph. How childish."] = "\"Chỉ Dàng Cho Ngừi Cá\"... hừm. Thật trẻ con."
    textfix["\"Mermfolk Ownlee\"? Hm. I see more spelling lessons are in order."] = "\"Chỉ giành cho người cá\"? Hm. Tôi thấy cần thêm vài bài học chính tả."
    textfix["\"Mermfolk ancestors definitely look like this, florp!\""] = "\"Tổ tiên của người cá chắc chắn trông như thế này, florp!\""
    textfix["\"Mermfolk known for hos-per-tality, florp.\""] = "\"Tộc Người Cá nổi tiếng mến-khách-lắm, florp.\""
    textfix["\"Mightiest Wolfgang is no heel!\""] = "\"Wolfgang mạnh nhất không phải phe phản diện!\""
    textfix["\"Mighty Alter, the source of our strength, our sole provider. We are loyal to none but You.\""] = "\"Alter Hùng Mạnh, nguồn sức mạnh của chúng tôi, đấng chu cấp duy nhất. Chúng tôi không trung thành với ai ngoài Ngài.\""
    textfix["\"Mighty Wolfgang cannot wait to step into ring!\""] = "\"Wolfgang hùng mạnh nóng lòng bước lên võ đài!\""
    textfix["\"Milk. Eggs. Bacon.\""] = "\"Sữa. Trứng. Thịt xông khói.\""
    textfix["\"Moon\" Figure"] = "Tượng \"Mặt Trăng\""
    textfix["\"Moon\" Figure Sketch"] = "Bản Thảo Tượng \"Mặt Trăng\""
    textfix["\"Moon\" Sketch"] = "Bản Phác Tượng Mặt Trăng"
    textfix["\"Moon\" detritus."] = "Mảnh vụn \"mặt trăng\"."
    textfix["\"Moon\" rock."] = "Đá \"mặt trăng\"."
    textfix["\"Much, much handsome\""] = "\"Đẹp trai, đẹp trai lắm\""
    textfix["\"Murder\", she wrote."] = "\"Giết người\", cô viết."
    textfix["\"Mwahahaha!\""] = "\"Muahahaha!\""
    textfix["\"My food's always burned to perfection!\""] = "\"Đồ ăn của tôi lúc nào cũng cháy khét hoàn hảo!\""
    textfix["\"My future will reveal itself in the phases of the moon.\""] = "\"Tương lai của tôi sẽ tự lộ diện theo các tuần trăng.\""
    textfix["\"My name shall live ön förever, as the scöurge öf the seven seas!\""] = "\"Tên tôi sẽ sống mãi, như nỗi kinh hoàng của bảy đại dương!\""
    textfix["\"My skill in battle is withöut peer.\""] = "\"Tài chiến đấu của tôi là vô song.\""
    textfix["\"My volcanic smoke shall encase the world in darkness.\""] = "\"Khói núi lửa của tôi sẽ vùi thế giới trong bóng tối.\""
    textfix["\"NOW THE OUTSIDE MATCHES THE INSIDE. EVIL.\""] = "\"GIỜ BÊN NGOÀI ĐÃ KHỚP VỚI BÊN TRONG. ÁC.\""
    textfix["\"Naughty. Definitely naughty.\""] = "\"Hư. Hư chắc luôn.\""
    textfix["\"New grown from old\""] = "\"Mới mọc ra từ cũ\""
    textfix["\"No beast withstandeth the will of one whose heart runneth wild.\""] = "\"Chẳng con thú nào cưỡng nổi ý chí của kẻ mang trái tim hoang dã.\""
    textfix["\"No longer doth the shadow stir terror within our hearts.\""] = "\"Bóng tối không còn khuấy động nỗi kinh hoàng trong trái tim chúng ta nữa.\""
    textfix["\"No! I'm the village GENIUS!\""] = "\"Không! Tôi là THIÊN TÀI của làng!\""
    textfix["\"Not enough people appreciate the minutiae of temporal tinkering.\""] = "\"Chẳng mấy ai biết trân trọng những chi tiết tỉ mỉ của việc mày mò thời gian.\""
    textfix["\"Not from fairy story... from scary story!\""] = "\"Không phải trong truyện cổ tích... trong truyện kinh dị!\""
    textfix["\"Not sick, just coffin.\""] = "\"Không ốm đâu, chỉ là... nằm hòm.\""
    textfix["\"Not yet mid-summer\", you say? Well my friend, the early bird gets the worm!"] = "\"Chưa đến giữa hè\", bạn nói? Bạn ơi, con chim sớm sẽ có sâu!"
    textfix["\"Nothing beats a golden croissant... I mean crescent.\""] = "\"Không gì sánh bằng một chiếc bánh sừng bò vàng óng... à, ý tôi là vầng trăng khuyết.\""
    textfix["\"Nothing here is what it seems. If you're reading this, keep an eye on the rabbits, don't trust the statues, and don't mistake that thing hanging in the night sky for the moon...\" -W"] = "\"Không có gì ở đây giống như vẻ bề ngoài cả. Nếu bạn đang đọc cái này, hãy để ý đến lũ thỏ, đừng tin vào những bức tượng và đừng nhầm thứ treo trên bầu trời đêm với mặt trăng...\" -W"
    textfix["\"Nothing is more fashionable than punctuality.\""] = "\"Chẳng gì hợp thời hơn việc đúng giờ.\""
    textfix["\"Nothing personal pal, the ice industry's a cold business.\""] = "\"Không có gì cá nhân đâu anh bạn, buôn băng là nghề lạnh lùng mà.\""
    textfix["\"Nothing worthwhile is ever done on an empty stomach!\""] = "\"Bụng đói thì chẳng làm nên việc gì ra hồn!\""
    textfix["\"OVERCHARGED, READY TO CHARGE\""] = "\"QUÁ TẢI NĂNG LƯỢNG, SẴN SÀNG HÚC\""
    textfix["\"OVERGROWN. CIRCUITS BLOWN\""] = "\"MỌC UM TÙM. CHÁY MẠCH\""
    textfix["\"Ode to the Scenery\""] = "\"Ca Ngợi Phông Nền\""
    textfix["\"Oh botheration, where have I gotten myself this time?\""] = "\"Ôi phiền quá, lần này mình lạc tới xó nào thế này?\""
    textfix["\"Oh dear, I have no idea where I'm going.\""] = "\"Ôi trời, tôi không biết mình sẽ đi đâu.\""
    textfix["\"Oh no, no!\" said the little fly"] = "\"Ồ không, không đâu!\" ruồi con đáp,"
    textfix["\"Oh yes, I'm cooking something up.\""] = "\"Ồ phải, tôi đang nấu ra một thứ đây.\""
    textfix["\"Ohh, my aching spines...\""] = "\"Ôi, mấy cái gai của tôi đau nhức quá...\""
    textfix["\"Ol'Kramps did always say; if I kept making a funny face it'd get stuck that way.\""] = "\"Lão Kramps vẫn luôn bảo: cứ nhăn mặt làm trò mãi thì có ngày mặt kẹt luôn như thế.\""
    textfix["\"Ol'Kramps says my powers should grow in soon. Hyuyu!\""] = "\"Lão Kramps bảo sức mạnh của tôi sắp mọc ra rồi. Hyuyu!\""
    textfix["\"Once I've perfected a recipe, I find it helpful to write it down. Luckily, I've been able to cobble together a rough cookbook for just such a thing out of some spare pieces of parchment. Now my mind is free to worry about more immediate things...\" -W"] = "\"Khi tôi đã hoàn thiện một công thức nấu ăn, tôi thấy việc viết nó ra sẽ rất hữu ích. May mắn thay, tôi đã có thể soạn ra một cuốn sách dạy nấu ăn thô sơ cho một món như vậy chỉ từ vài mảnh giấy da thừa. Bây giờ tâm trí tôi có thể tự do lo lắng về những việc trước mắt hơn...\" -W"
    textfix["\"One must either offer a tribute, or become the tribute.\""] = "\"Hoặc là dâng cống phẩm, hoặc là trở thành cống phẩm.\""
    textfix["\"One of the simplest ways to invite rain is to kill a-\" oh..."] = "\"Một trong những cách đơn giản nhất để mời mưa là giết-\" ồ..."
    textfix["\"Only the strongest spiders survive out here!\""] = "\"Ở ngoài này chỉ những con nhện mạnh nhất mới sống sót!\""
    textfix["\"Only when all torches burn shall the way be revealed.\""] = "\"Chỉ khi mọi ngọn đuốc đều cháy sáng, lối đi mới được hé lộ.\""
    textfix["\"Ook OOK!\""] = "\"Hú HÚ! Khẹc KHẸC!\""
    textfix["\"Orphans cast upon the barren expanse. Lost in the wake of neglect.\""] = "\"Những đứa trẻ mồ côi bị bỏ rơi trên vùng đất cằn cỗi. Lạc lối vì bị bỏ rơi.\""
    textfix["\"PIRACY WARNING\""] = "\"CẢNH BÁO: PHÁT HIỆN CƯỚP BIỂN\""
    textfix["\"PRACTICE\"... HOW ORGANIC"] = "\"LUYỆN TẬP\"... ĐÚNG LÀ HỮU CƠ"
    textfix["\"PREPARING TO DIVE\""] = "\"CHUẨN BỊ LẶN\""
    textfix["\"PROGRAMMED IN LAVASCRIPT\""] = "\"ĐƯỢC LẬP TRÌNH BẰNG LAVASCRIPT\""
    textfix["\"Pardon me if I don't shake your hand.\""] = "\"Xin lỗi nếu tôi không bắt tay bạn.\""
    textfix["\"Paths are taken but once. Leap wisely, tarry not, or the abyss claims all.\""] = "\"Con đường chỉ được bước qua một lần. Hãy nhảy một cách khôn ngoan, đừng chần chừ, nếu không vực thẳm sẽ nuốt chửng tất cả.\""
    textfix["\"Perhaps I was wrong to dismiss the moon's power so quickly...\""] = "\"Có lẽ tôi đã sai khi vội xem thường sức mạnh của mặt trăng...\""
    textfix["\"Perhaps I'll retire to a life of rose breeding.\""] = "\"Có lẽ tôi sẽ về hưu và đi lai tạo hoa hồng.\""
    textfix["\"Play with fire and you'll get burned.\""] = "\"Chơi với lửa thì có ngày bỏng tay.\""
    textfix["\"Please come home. I miss you so much.\""] = "\"Anh về nhà đi. Em nhớ anh nhiều lắm.\""
    textfix["\"Plum\" is a 17th century term for \"fruit\", dear."] = "\"Plum\" là từ thế kỷ 17 dùng để chỉ \"trái cây\", cháu à."
    textfix["\"Potato purée\" is so much more fun to say than \"mashed potatoes\"."] = "Gọi là \"purée khoai tây\" nghe vui tai hơn hẳn \"khoai tây nghiền\"."
    textfix["\"Quiet your voice here. The trees slumber.\""] = "\"Nói khẽ thôi. Cây cối đang ngủ.\""
    textfix["\"Quoth the tallbird, Evermore.\""] = "\"Chim Cao phán rằng: Mãi mãi.\""
    textfix["\"RUSTED AND BUSTED\""] = "\"GỈ SÉT VÀ HỎNG HÓC\""
    textfix["\"Raaar! ...That's our bat noise.\""] = "\"Graaa! ...Đó là tiếng dơi của chúng mình đấy.\""
    textfix["\"Raisins\""] = "\"Nho Khô\""
    textfix["\"Recipes are useful, but a true chef knows the importance of experimenting with new ingredients and flavors, and this world certainly provides an abundance of unusual things to choose from.\" -W"] = "\"Các công thức nấu ăn rất hữu ích, nhưng một đầu bếp thực thụ biết tầm quan trọng của việc thử nghiệm các nguyên liệu và hương vị mới, và thế giới này chắc chắn có vô số điều khác thường để bạn lựa chọn.\" -W"
    textfix["\"Rule one: don't set beehives on fire\"? This book's stupid!"] = "\"Quy tắc thứ nhất: không được đốt tổ ong\"? Cuốn sách này thật ngu ngốc!"
    textfix["\"Say, pal, I don't look so good.\""] = "\"Này anh bạn, trông tôi không ổn lắm.\""
    textfix["\"Science says I'll be nipping at your nose.\""] = "\"Khoa học nói rằng tôi sẽ cắn nhẹ mũi bạn đấy.\""
    textfix["\"Shadows are as black as ink, or night, or nightmares.\""] = "\"Bóng tối đen như mực, như màn đêm, như những cơn ác mộng.\""
    textfix["\"Shadows are just inverted flames.\""] = "\"Bóng tối chỉ là ngọn lửa đảo ngược.\""
    textfix["\"Shhhh! No talking!\""] = "\"Xuỵtttt! Không nói chuyện!\""
    textfix["\"Sir Wolfgang is strongest boxer!\""] = "\"Ngài Wolfgang là võ sĩ mạnh nhất!\""
    textfix["\"Snowy peaks are a Canadian's natural habitat.\""] = "\"Đỉnh núi tuyết là môi trường sống tự nhiên của dân Canada.\""
    textfix["\"So alluring...\""] = "\"Thật lôi cuốn...\""
    textfix["\"So few dare to delve into the secrets of dark magic.\""] = "\"Hiếm ai dám đào sâu vào những bí mật của ma thuật hắc ám.\""
    textfix["\"So many toys to build, and so little time!\""] = "\"Bao nhiêu đồ chơi phải làm, mà thời gian thì chẳng còn bao nhiêu!\""
    textfix["\"So... does anyone work around here, or is it all festival all the time?\""] = "\"Vậy... có ai làm việc quanh đây không, hay lúc nào cũng là lễ hội?\""
    textfix["\"Someone\" had far too much time on his hands..."] = "\"Ai đó\" có quá nhiều thời gian rảnh..."
    textfix["\"Something is different... Wolfgang's head feels fuzzy...\""] = "\"Có gì đó khác lạ... đầu Wolfgang thấy xù xù, lâng lâng...\""
    textfix["\"Sometimes the old ways need to crash and burn to make way for the new.\""] = "\"Đôi khi cái cũ phải sụp đổ và cháy rụi để nhường chỗ cho cái mới.\""
    textfix["\"Sorry\"'s not gonna cut it this time!"] = "\"Xin lỗi\" lần này sẽ không hiệu quả đâu!"
    textfix["\"Spoooooky!\""] = "\"Ma quáiiiii!\""
    textfix["\"Stand back. I'm going to do SCIENCE!\""] = "\"Lùi lại. Tôi sắp làm KHOA HỌC đây!\""
    textfix["\"Starlight is a blast from the past.\""] = "\"Ánh sao là một vụ nổ từ quá khứ.\""
    textfix["\"Surviving just requires strength of will. (And fire.)\""] = "\"Sống sót chỉ cần ý chí mạnh mẽ. (Và lửa.)\""
    textfix["\"Sweet slumber.\""] = "\"Giấc ngủ ngọt ngào.\""
    textfix["\"Swirly shiny!\""] = "\"Xoắn xoắn lấp lánh!\""
    textfix["\"THATAWAY\""] = "\"ĐẰNG KIA\""
    textfix["\"THE MOON AND I HAVE PLANS. GREAT PLANS\""] = "\"MẶT TRĂNG VÀ TÔI CÓ KẾ HOẠCH. KẾ HOẠCH LỚN\""
    textfix["\"THEY HAVE NOT INSTALLED A HEART\""] = "\"HỌ CHƯA LẮP TRÁI TIM\""
    textfix["\"THIS UNIT IS BATTLE READY\""] = "\"ĐƠN VỊ NÀY ĐÃ SẴN SÀNG CHIẾN ĐẤU\""
    textfix["\"That village was burnt before I got there.\""] = "\"Ngôi làng đó cháy từ trước khi tôi tới rồi.\""
    textfix["\"That's a nice lookin' tree, eh? Not for long.\""] = "\"Cái cây trông đẹp đấy nhỉ? Chẳng được lâu đâu.\""
    textfix["\"Thataway\"... Ugh!"] = "\"Lối kia\"... Ugh!"
    textfix["\"The Blacksmith's Soliloquy\""] = "\"Độc Thoại của Thợ Rèn\""
    textfix["\"The Fool's Soliloquy\""] = "\"Độc Thoại Của Kẻ Khờ\""
    textfix["\"The Frogs Who Desired a King\"..."] = "\"Những chú ếch mong muốn có một vị vua\"..."
    textfix["\"The King's Soliloquy\""] = "\"Độc Thoại của Nhà Vua\""
    textfix["\"The Merms are fiercely territorial, and quick to defend their homes. Though I honestly can't imagine anyone else wanting to take up residence in those ram-shackle hovels...\" -M"] = "\"Người Cá có tính lãnh thổ quyết liệt và nhanh chóng bảo vệ ngôi nhà của mình. Mặc dù thực lòng tôi không thể tưởng tượng được có ai khác muốn cư trú trong những túp lều lụp xụp đó...\" -M"
    textfix["\"The Pig men seem to harbor a deep dislike for the Constant's more monstrous denizens, attacking them on sight. While I personally can't blame them, it does pose a bit of a problem for some of my compatriots...\" -W"] = "\"Người Lợn dường như rất ghét những cư dân quái dị hơn của Constant, hễ thấy là tấn công. Tuy cá nhân tôi không trách họ, nhưng điều đó gây ra chút rắc rối cho vài người bạn đồng hành của tôi...\" -W"
    textfix["\"The Reunion\""] = "\"Cuộc hội ngộ\""
    textfix["\"The arm bone's connected to the...\" which bone was it..."] = "\"Xương cánh tay nối với...\" xương nào ấy nhỉ..."
    textfix["\"The bushes I replanted by the camp are looking sickly... I suspect they'll require some extra care before they can produce any berries again.\" -W"] = "\"Những bụi cây tôi trồng lại gần trại trông ốm yếu... Tôi nghi ngờ chúng sẽ cần được chăm sóc thêm trước khi có thể ra quả trở lại.\" -W"
    textfix["\"The cosmos are filled with limitless scientific possibilities!\""] = "\"Vũ trụ chứa đầy những khả năng khoa học vô hạn!\""
    textfix["\"The flames taught me how to dance.\""] = "\"Ngọn lửa dạy tôi cách nhảy.\""
    textfix["\"The hills will ring with Wolfgang's mighty yodels!\""] = "\"Núi đồi sẽ vang vọng tiếng hát ngân nga hùng tráng của Wolfgang!\""
    textfix["\"The life of the party has arrived!\""] = "\"Linh hồn của bữa tiệc đã tới đây!\""
    textfix["\"The moon in this world seems to hold some strange power over the creatures here. It changes them...\" -W"] = "\"Mặt trăng ở thế giới này dường như có sức mạnh kỳ lạ nào đó đối với các sinh vật ở đây. Nó thay đổi chúng...\" -W"
    textfix["\"The moon made us... different.\""] = "\"Mặt trăng đã khiến chúng tôi... khác đi.\""
    textfix["\"The night is young, but not for long.\""] = "\"Đêm vẫn còn dài, nhưng chẳng dài được lâu.\""
    textfix["\"The poor unsuspecting fool has no idea what's coming.\""] = "\"Gã ngốc đáng thương nhẹ dạ chẳng biết điều gì sắp xảy đến.\""
    textfix["\"The rain is proving to be a greater hindrance than I first anticipated. As if being soaked to the bone isn't dreadful enough, my tools keep slipping from my hands when I try to make use of them!\" -W"] = "\"Mưa đang trở thành một trở ngại lớn hơn tôi dự đoán ban đầu. Như thể việc ướt sũng đến tận xương vẫn chưa đủ khủng khiếp, các dụng cụ của tôi cứ tuột khỏi tay khi tôi cố gắng sử dụng chúng!\" -W"
    textfix["\"The root of all malady lies in an imbalance of the humors.\""] = "\"Căn nguyên của mọi bệnh tật nằm ở sự mất cân bằng thể dịch.\""
    textfix["\"The rose shelters our fur from the morning dew.\""] = "\"Bông hồng che cho bộ lông của chúng tôi khỏi sương sớm.\""
    textfix["\"The sea shows no mercy to fools - and neither will I.\""] = "\"Biển không thương xót những kẻ ngốc - và tôi cũng vậy.\""
    textfix["\"The stage is set för my rise tö glöry!\""] = "\"Sân khấu đã sẵn sàng cho tôi vươn tới vinh quang!\""
    textfix["\"The thorned rose cannot help but prick. It is its nature.\""] = "\"Hoa hồng gai không thể không chích. Đó là bản chất của nó.\""
    textfix["\"The unknown hath been made known. The abyss revealed as refuge.\""] = "\"Điều chưa biết đã được biết đến. Vực thẳm được tiết lộ là nơi ẩn náu.\""
    textfix["\"The wheel on the gym goes round and round.\""] = "\"Bánh xe máy tập cứ quay, quay mãi.\""
    textfix["\"There is a scientific solution, here. I know it.\""] = "\"Ở đây có một giải pháp khoa học. Tôi biết mà.\""
    textfix["\"There is magic in the trees.\""] = "\"Cây cối cũng ẩn chứa phép thuật.\""
    textfix["\"There is nothing but dark times ahead.\""] = "\"Phía trước chỉ toàn những thời khắc đen tối.\""
    textfix["\"There'll be no slip-ups while I'm in charge!\""] = "\"Có tôi trông coi thì đừng hòng có ai trượt chân!\""
    textfix["\"There's a time to work, and a time to Charleston!\""] = "\"Có lúc để làm việc, và có lúc để nhảy Charleston!\""
    textfix["\"There's always more to do than there is time to do it.\""] = "\"Luôn có nhiều việc phải làm hơn là có thời gian để làm.\""
    textfix["\"There's few things more satisfying than watchin' something grow.\""] = "\"Hiếm có gì mãn nguyện bằng ngắm một thứ lớn lên từng ngày.\""
    textfix["\"These masked events are the playgrounds of merry mischief-makers!\""] = "\"Những sự kiện đeo mặt nạ này là sân chơi của những kẻ nghịch ngợm vui vẻ!\""
    textfix["\"These old threads I dug up aren't half bad, eh?\""] = "\"Mớ đồ cũ tôi đào được cũng đâu tệ lắm, hả?\""
    textfix["\"They ain't beaver pelts, I'll tell ya that much.\""] = "\"Nói trước nhé, cái này không phải da hải ly đâu.\""
    textfix["\"They say the Shadow Queen herself comes at night to snatch up anyone foolish enough to wander in the dark...\" -W"] = "\"Người ta nói rằng Nữ hoàng Bóng tối đích thân đến vào ban đêm để tóm lấy bất cứ ai đủ ngu ngốc để đi lang thang trong bóng tối...\" -W"
    textfix["\"This Waymark is under development for a future update.\""] = "\"Mốc Dẫn Lối này đang được phát triển cho bản cập nhật trong tương lai.\""
    textfix["\"This is where I keep my stuff.\""] = "\"Đây là nơi tôi giữ đồ đạc của mình.\""
    textfix["\"This lunar knowledge has been quite... eye-opening.\""] = "\"Tri thức về mặt trăng này quả thật... mở mang tầm mắt.\""
    textfix["\"This match will require a few more adjournments.\""] = "\"Ván cờ này sẽ cần hoãn thêm vài lần nữa.\""
    textfix["\"This may prove to be my most dangerous experiment yet.\""] = "\"Đây có thể là thí nghiệm nguy hiểm nhất của tôi từ trước đến giờ.\""
    textfix["\"This vault shall become a tomb for all who dare trespass.\""] = "\"Hầm này sẽ trở thành lăng mộ cho bất kỳ kẻ nào dám xâm phạm.\""
    textfix["\"This world could not hold me.\""] = "\"Thế giới này không thể giữ tôi.\""
    textfix["\"This\" likely connects to a \"that.\""] = "“Cái này” có thể kết nối với “cái kia”."
    textfix["\"Thou art called by manifold names in myriad realms.\""] = "\"Ngươi được gọi bằng nhiều tên trong vô số cõi.\""
    textfix["\"Thought and conscientiousness nips all problems in the bud.\""] = "\"Chu đáo và cẩn trọng thì rắc rối nào cũng dập tắt từ trong trứng nước.\""
    textfix["\"Through the Keystone, all kin and kind shall fall.\""] = "\"Thông qua Đá Khóa, mọi thân tộc và giống loài sẽ sụp đổ.\""
    textfix["\"Time seems to move slower in the depths of the forest.\""] = "\"Thời gian dường như trôi chậm hơn trong rừng sâu.\""
    textfix["\"Time to roll up my sleeves.\""] = "\"Tới lúc xắn tay áo lên rồi.\""
    textfix["\"Time! I just need more time!\""] = "\"Thời gian! Tôi chỉ cần thêm thời gian!\""
    textfix["\"To change?\" No. It's a name..."] = "\"Thay đổi?\" Không. Đó là một cái tên..."
    textfix["\"To chop the tree, you must be the tree.\""] = "\"Để chặt cây, bạn phải là cây.\""
    textfix["\"To us, Thou art Shrouden. Many and one. Beyond all time. Beyond all realms.\""] = "\"Với chúng tôi, Ngài là Shrouden. Vừa nhiều vừa một. Vượt trên mọi thời gian. Vượt trên mọi cõi.\""
    textfix["\"Today I was surprised to come upon a cobbled road - how did this hallmark of civilization come to be in this untamed wilderness?\" -W"] = "\"Hôm nay tôi rất ngạc nhiên khi bắt gặp một con đường rải sỏi - làm thế nào mà dấu ấn của nền văn minh này lại xuất hiện ở vùng hoang dã hoang sơ này?\" -W"
    textfix["\"Tough as obsidian.\""] = "\"Cứng như đá vỏ chai.\""
    textfix["\"Transdermal Induction Neurological Galvanic Learning Experience\" Uses electrolunetic technology to deliver shocks to conductive entities.\n\nOnce toggled, the T.I.N.G.L.E. node will search for another nearby node to link to, establishing an electric field between the two.\n\nNo physical harm is done (mental harm is up for debate). Most subjects will flee away after the brief shock.\n\nThe tester is recommended to use insulative gear to avoid this special learning experience!"] = "\"Trải Nghiệm Học Tập Điện Thần Kinh Cảm Ứng Qua Da\". Dùng công nghệ điện nguyệt để phóng điện vào các thực thể dẫn điện.\n\nKhi được bật, Nút T.I.N.G.L.E. sẽ tìm một nút khác ở gần để liên kết, tạo ra một điện trường giữa hai nút.\n\nKhông gây tổn hại thể xác (còn tổn hại tinh thần thì vẫn còn phải bàn). Hầu hết đối tượng sẽ bỏ chạy sau cú giật ngắn.\n\nNgười thử nghiệm nên dùng đồ cách điện để tránh trải nghiệm học tập đặc biệt này!"
    textfix["\"Trust none. The Shadow twists all it touches.\""] = "\"Đừng tin bất kỳ ai. Bóng Tối bóp méo mọi thứ nó chạm vào.\""
    textfix["\"Try not to cower in fear, my dear!\""] = "\"Cố gắng không thu mình lại vì sợ hãi, em yêu!\""
    textfix["\"Volcanic power is intoxicating.\""] = "\"Sức mạnh núi lửa thật khiến người ta say sưa.\""
    textfix["\"WITH PARTS MADE IN JAPAN\""] = "\"VỚI LINH KIỆN SẢN XUẤT TẠI NHẬT BẢN\""
    textfix["\"Want to hear a really scary story?\""] = "\"Bạn muốn nghe một câu chuyện thực sự đáng sợ?\""
    textfix["\"Watch for my extrusive igneous rocks, dear.\""] = "\"Coi chừng đá mácma phun trào của ta đấy, cháu yêu.\""
    textfix["\"We all turn cold in time.\""] = "\"Rồi ai cũng sẽ lạnh đi theo thời gian.\""
    textfix["\"We are what we eat... sweet!\""] = "\"Ăn gì thì thành nấy... ngọt ngào ghê!\""
    textfix["\"We don't want to fight if we don't have to.\""] = "\"Chúng tôi không muốn đánh nhau nếu không bắt buộc.\""
    textfix["\"We impish sorts do love our gold, hyuyu!\""] = "\"Lũ tinh quái bọn tôi mê vàng lắm, hyuyu!\""
    textfix["\"We like parties!\""] = "\"Chúng tôi thích các bữa tiệc!\""
    textfix["\"We love playing in the snow!\""] = "\"Chúng tôi thích chơi trong tuyết!\""
    textfix["\"We nearly lost one of our number today. In a mad daze I created... something... that managed to pull our friend back to the land of the living, but... whatever it was, I fear I cannot rightfully say it was within the realm of science...\" -W"] = "\"Hôm nay chúng ta gần như mất đi một người. Trong cơn choáng váng điên cuồng, tôi đã tạo ra... thứ gì đó... có thể kéo bạn của chúng tôi trở lại vùng đất của người sống, nhưng... dù đó là gì đi nữa, tôi e rằng tôi không thể nói một cách đúng đắn rằng nó nằm trong lĩnh vực khoa học...\" -W"
    textfix["\"We remain faithful to Alter, as Alter remains faithful to us. Ever watching, knowing, waiting.\""] = "\"Chúng tôi mãi trung thành với Alter, như Alter mãi trung thành với chúng tôi. Luôn dõi theo, thấu hiểu, chờ đợi.\""
    textfix["\"We shouldn't hurt things that don't hurt us. If we're mean, bad old Mr. Krampus will come...\" -W"] = "\"Chúng ta không nên làm tổn thương những thứ không làm tổn thương chúng ta. Nếu chúng ta xấu tính, ông già Krampus xấu xa sẽ đến...\" -W"
    textfix["\"We were so lonely back then...\""] = "\"Hồi ấy chúng tôi cô đơn lắm...\""
    textfix["\"We will celebrate as if we were in Valhalla!\""] = "\"Chúng ta sẽ ăn mừng như thể đang ở Valhalla!\""
    textfix["\"We'll be on our best behavior... probably.\""] = "\"Chúng tôi sẽ cư xử tốt nhất... có lẽ vậy.\""
    textfix["\"We're always together, and never alone!\""] = "\"Chúng tôi luôn bên nhau, và không bao giờ cô đơn!\""
    textfix["\"We're going to play until the sun goes down, and then we're going to play some more.\""] = "\"Chúng mình sẽ chơi tới khi mặt trời lặn, rồi chơi thêm chút nữa.\""
    textfix["\"We're like a walking volcano.\""] = "\"Chúng tôi như một ngọn núi lửa biết đi.\""
    textfix["\"We're super excited to watch everyone open the presents we got them.\""] = "\"Chúng mình háo hức lắm, muốn xem mọi người mở quà chúng mình tặng.\""
    textfix["\"Well, A Rather Beautifully Intelligent System.\" Uses a complicated assortment of cogs and circuitry for computing.\n\nOnce a target has been selected, as long as it stays in range, the W.A.R.B.I.S. begins calculating optimal performance to fight the target.\n\nThe armor improves the wearer's speed as it analyzes the target, ending at a 30% speed boost.\n\nWhen combined with the W.A.R.B.I.S. headgear, the two will sync up for a few moments sharing target information."] = "\"Chà, Một Hệ Thống Thông Minh Khá Đẹp.\" Dùng cả một mớ bánh răng và mạch điện phức tạp để tính toán.\n\nKhi đã chọn mục tiêu, miễn là mục tiêu còn trong tầm, W.A.R.B.I.S. sẽ bắt đầu tính toán cách chiến đấu tối ưu với nó.\n\nTrong lúc phân tích mục tiêu, bộ giáp tăng dần tốc độ của người mặc, tối đa là tăng 30% tốc độ.\n\nKhi mặc cùng Nón W.A.R.B.I.S., hai món sẽ đồng bộ trong giây lát để chia sẻ thông tin mục tiêu."
    textfix["\"Well, A Rather Beautifully Intelligent System.\" Uses a complicated assortment of cogs and circuitry for computing.\n\nOnce a target has been selected, as long as it stays in range, the W.A.R.B.I.S. begins calculating optimal performance to fight the target.\n\nThe head gear improves the wearer's damage as it analyzes the target, ending at a 20% damage increase.\n\nWhen combined with the W.A.R.B.I.S. armor, the two will sync up for a few moments sharing target information.\n\nWearing the W.A.R.B.I.S. Head Gear also provides the wearer with a Dramatically Updating Diagram (or D.U.D.) which provides information on which target is currently being analyzed and what level the W.A.R.B.I.S. has reached."] = "\"Chà, Một Hệ Thống Thông Minh Khá Đẹp.\" Dùng cả một mớ bánh răng và mạch điện phức tạp để tính toán.\n\nKhi đã chọn mục tiêu, miễn là mục tiêu còn trong tầm, W.A.R.B.I.S. sẽ bắt đầu tính toán cách chiến đấu tối ưu với nó.\n\nTrong lúc phân tích mục tiêu, chiếc nón tăng dần sát thương của người đội, tối đa là tăng 20% sát thương.\n\nKhi đội cùng Giáp W.A.R.B.I.S., hai món sẽ đồng bộ trong giây lát để chia sẻ thông tin mục tiêu.\n\nĐội Nón W.A.R.B.I.S. còn cho người đội một Sơ Đồ Cập Nhật Liên Tục (hay D.U.D.), hiển thị mục tiêu nào đang được phân tích và W.A.R.B.I.S. đã đạt tới cấp độ nào."
    textfix["\"Well, at least Lucy thinks it's scary!\""] = "\"Chà, ít nhất Lucy nghĩ rằng nó đáng sợ!\""
    textfix["\"Well, what d'ya know? I scrub up mighty fine when I feel like it.\""] = "\"Chà, ai mà ngờ? Khi muốn thì tôi cũng chải chuốt ra dáng lắm chứ.\""
    textfix["\"Whaddya say we get the gang together for some carols?\""] = "\"Rủ cả hội đi hát vài bài mừng lễ nhé, thấy sao?\""
    textfix["\"What a treat it is to rub shoulders with the creme de la creme!\""] = "\"Được giao du với giới thượng lưu, crème de la crème, quả là một đặc ân!\""
    textfix["\"What strange new islands and creatures might I encounter if I journey out to sea? I shudder to think... but curiosity has a tendency to get the better of me...\" -W"] = "\"Tôi có thể gặp những hòn đảo và sinh vật mới lạ nào nếu ra khơi? Tôi rùng mình khi nghĩ... nhưng trí tò mò có xu hướng lấn át tôi...\" -W"
    textfix["\"What... happening...? Feel... strange...\""] = "\"Chuyện gì... đang xảy ra...? Thấy... lạ lắm...\""
    textfix["\"Where are you Abigail? I thought I'd find you among the stars...\""] = "\"Abigail, em ở đâu? Chị tưởng sẽ tìm thấy em giữa các vì sao...\""
    textfix["\"Where should we go on our next adventure, Woby?\""] = "\"Chúng ta nên đi đâu trong chuyến phiêu lưu tiếp theo, Woby?\""
    textfix["\"Whoops.\""] = "\"Ối.\""
    textfix["\"Why couldn't it be warm fire?\""] = "\"Sao không phải là lửa ấm chứ?\""
    textfix["\"Why did you leave me?\""] = "\"Sao lại bỏ rơi tôi?\""
    textfix["\"Will you walk into my parlour?\""] = "\"Vào phòng khách của ta chơi nhé?\""
    textfix["\"Winter Feast is Wolfgang favorite time of year.\""] = "\"Lễ hội mùa đông là thời điểm Wolfgang yêu thích nhất trong năm.\""
    textfix["\"Woah, I'm smokin'! (No, really!)\""] = "\"Ồ, tôi nóng bỏng quá! (Nóng thật đấy!)\""
    textfix["\"Wolfgang is large moustache man! Ha ha!\""] = "\"Wolfgang là người đàn ông ria mép lớn! Ha ha!\""
    textfix["\"Wolfgang is learning much about history.\""] = "\"Wolfgang đang tìm hiểu nhiều về lịch sử.\""
    textfix["\"Wolfgang is mightiest pirate on the sea!\""] = "\"Wolfgang là cướp biển hùng mạnh nhất trên biển!\""
    textfix["\"Wolfgang is mighty man of the land!\""] = "\"Wolfgang là người hùng mạnh của đất này!\""
    textfix["\"Wolfgang is on the fire.\""] = "\"Wolfgang đang rực lửa!\""
    textfix["\"Wolfgang is strongest there ever was!\""] = "\"Wolfgang mạnh nhất từ trước tới nay!\""
    textfix["\"Wolfgang is tough. Lots of muscle.\""] = "\"Wolfgang rắn rỏi. Cơ bắp cuồn cuộn.\""
    textfix["\"Wolfgang will carry moon to victory!\""] = "\"Wolfgang sẽ mang mặt trăng đến chiến thắng!\""
    textfix["\"Wolfgang will cook for you!\""] = "\"Wolfgang sẽ nấu ăn cho bạn!\""
    textfix["\"Won't you visit me at the heart of the labyrinth?\""] = "\"Sao bạn không ghé thăm tôi giữa lòng mê cung?\""
    textfix["\"Would you like a sweetie, dear?\""] = "\"Cháu có muốn một viên kẹo không, cháu yêu?\""
    textfix["\"Wörds, wörds, wörds.\""] = "\"Chữ, chữ, chữ.\""
    textfix["\"X marks the spot\", eh?"] = "\"X đánh dấu vị trí\", hả?"
    textfix["\"YOU ARE HERE\""] = "\"BẠN ĐANG Ở ĐÂY\""
    textfix["\"Yacht not included.\""] = "\"Không kèm du thuyền.\""
    textfix["\"You are but a cog in my machine.\""] = "\"Bạn chỉ là một bánh răng trong máy của tôi.\""
    textfix["\"You are here\" it says, it says."] = "\"Bạn đang ở đây\" nó nói, nó nói."
    textfix["\"You are here\"... I wish I wasn't!"] = "\"Bạn đang ở đây\"... Tôi ước gì tôi không ở đây!"
    textfix["\"You are old, Father William,\" the young man said"] = "\"Cha William ơi, cha già rồi,\" chàng trai nói,"
    textfix["\"You can't run from Them forever. Take it from me, pal.\" -M"] = "\"Cậu không thể chạy trốn khỏi Chúng mãi được đâu. Tin tôi đi, anh bạn.\" -M"
    textfix["\"You expect me to mingle? I was assured I'd have my own private box seat!\""] = "\"Các người muốn tôi đi giao lưu à? Tôi đã được đảm bảo có hẳn một lô ghế riêng cơ mà!\""
    textfix["\"You know what they say, you can't get charcoal without burning down a few trees!\" -W"] = "\"Bạn biết người ta nói gì không, bạn không thể kiếm được than nếu không đốt vài cái cây!\" -W"
    textfix["\"You live fast out here... or not at all.\""] = "\"Ở chốn này, sống thì phải sống nhanh... hoặc chẳng sống nổi.\""
    textfix["\"You scullion! You rampallian! You fustilarian! I'll tickle your catastrophe!\""] = "\"Đồ hầu bếp hèn mạt! Đồ vô lại! Đồ lăng loàn! Ta sẽ đá đít ngươi!\""
    textfix["\"You seem to think you got a chance. Let's fix that.\""] = "\"Cậu có vẻ nghĩ mình có cửa thắng. Để tôi sửa lại cái suy nghĩ đó.\""
    textfix["\"You will kneel before might of Wolfgang!\""] = "\"Các ngươi sẽ phải quỳ trước sức mạnh của Wolfgang!\""
    textfix["\"You, sir! How about a shave?\""] = "\"Thưa ngài! Cạo râu một chút chứ?\""
    textfix["\"Yöu have tö try harder than this tö defeat me!\""] = "\"Muốn đánh bại tôi thì phải cố hơn thế này nhiều!\""
    textfix["'Begs the question blue' colored dancing pants."] = "Quần khiêu vũ màu 'xanh khó hiểu'."
    textfix["'Cobaltous oxide blue' colored gloves suitable for all types of persons, robots, and monsters."] = "Găng tay màu 'xanh coban oxit' phù hợp với mọi loại người, robot và quái vật."
    textfix["'Crow blue' colored stripy trousers."] = "Quần sọc nhỏ màu 'xanh Quạ'."
    textfix["'Cumulus gray' colored gloves suitable for all types of persons, robots, and monsters."] = "Găng tay màu 'xám mây tích' hợp với mọi loại người, robot và quái vật."
