    textfix["Wendy Hand-Me-Downs Chest"] = "Rương Đồ Cũ Truyền Lại Của Wendy"
    textfix["Wendy Magmatic Chest"] = "Rương Dung Nham Wendy"
    textfix["Wendy Masquerader Chest"] = "Rương Kẻ Đeo Mặt Nạ Wendy"
    textfix["Wendy Merrymaker Chest"] = "Rương Hội Hè Wendy"
    textfix["Wendy Moonbound Chest"] = "Rương Nhuốm Trăng Wendy"
